package com.dexm.personajes.adapter.out.persistence;
import jakarta.persistence.*;
@Entity @Table(name="physical_shield_catalog") public class PhysicalShieldCatalogEntity { @Id private String id; @Column(nullable=false) private String name; @Column(columnDefinition="text") private String description; @Column(nullable=false) private int rd; @Column(nullable=false) private int armor; @Column(nullable=false) private int defense; @Column(name="other_effects",columnDefinition="text") private String otherEffects; @Column(name="image_url",columnDefinition="longtext") private String imageUrl; @Column(nullable=false) private boolean official; protected PhysicalShieldCatalogEntity(){} public PhysicalShieldCatalogEntity(String i,String n,String d,int r,int a,int f,String e,String u,boolean o){id=i;name=n;description=d;rd=r;armor=a;defense=f;otherEffects=e;imageUrl=u;official=o;} public String getId(){return id;} public String getName(){return name;} public String getDescription(){return description;} public int getRd(){return rd;} public int getArmor(){return armor;} public int getDefense(){return defense;} public String getOtherEffects(){return otherEffects;} public String getImageUrl(){return imageUrl;} public boolean isOfficial(){return official;} }
